// Cigars category is id 2 (hardcoded). Both HTTP nodes are executeOnce,
// so each POS endpoint is called exactly one time per run.
const report = $('Fetch Not Scanned').all().map(i => i.json);
const cigarItems = $('Fetch Cigar Items').all().map(i => i.json);

const cigarNumbers = new Set();
const cigarNames = new Set();
for (const it of cigarItems) {
  if (it.item_inactive === true) continue;
  if (it.item_number) cigarNumbers.add(String(it.item_number).trim().toLowerCase());
  if (it.item_id) cigarNumbers.add(String(it.item_id).trim().toLowerCase());
  if (it.name) cigarNames.add(String(it.name).trim().toLowerCase());
}

let rows = [];
for (const r of report) {
  if (r && r.data && Array.isArray(r.data.rows)) rows = rows.concat(r.data.rows);
  else if (r && Array.isArray(r.details)) rows = rows.concat(r.details);
  else if (r && r.data && Array.isArray(r.data)) rows = rows.concat(r.data);
}

function pick(obj, keys) {
  for (const k of keys) {
    for (const actual of Object.keys(obj)) {
      if (actual.toLowerCase().replace(/[^a-z]/g,'') === k) return obj[actual];
    }
  }
  return '';
}

// Run date in America/New_York, as YYYY-MM-DD
const snapshotDate = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });

const out = [];
for (const row of rows) {
  const num = String(pick(row, ['itemnumber','sku','item','number','itemid']) || '').trim();
  const nm  = String(pick(row, ['name','itemname','description']) || '').trim();
  if (!((num && cigarNumbers.has(num.toLowerCase())) ||
        (nm  && cigarNames.has(nm.toLowerCase())))) continue;

  const qtyRaw = pick(row, ['quantity','onhand','instock','qty']);
  const qty = qtyRaw === '' || qtyRaw === null || qtyRaw === undefined
    ? null : Number(String(qtyRaw).replace(/[^0-9.\-]/g, ''));

  out.push({
    json: {
      snapshot_date: snapshotDate,
      sku: num || null,
      name: nm || null,
      on_hand: (qty === null || isNaN(qty)) ? null : qty
    }
  });
}

if (out.length === 0) {
  return [{ json: { snapshot_date: snapshotDate, sku: null, name: 'NO CIGARS RETURNED', on_hand: null } }];
}
return out;
